// UWindow.h// Copyright © 1984-2001 by Apple Computer. All rights reserved. /*	Change History		06/18/01	Modify "ResizableWindow" to handle the fact that the resize limits					could be 0.		06/14/01	Create inline "ResizableWindow" to help better determine when					to draw the resize icon.		01/24/01	Restore fStrListID, fIndex, fDisposeOnFree, fSubStart and fTailLength					which were accidentally lost.		01/11/01	Eliminated ParseTitleTemplate.		01/05/01	Change to use CString_AC instead of std::string and CStr255_AC.		12/28/00	Replaced fPreDocname and fConstTitle with fSubStart and fTailLength.					string is now used instead of CStr255_AC.  Include string.		01/02/01	Update copyright.		12/28/00	CreateAppearanceWindow is PowerPC only. 		12/27/00	Use CWindow_AC. Rename CreateWindow to CreateToolboxWindow to					avoid conflict with a Windows macro. 		12/26/00	[W] Added fZoomedOut.		12/15/00	Split off CreateWindow and ParseTitleTemplate from ReadFields. 		12/11/00	[C] Include CCarbonEvents_AC only if qCarbonEvents. 		12/08/00	[C] Add separate methods for different Carbon event classes. 		12/05/00	[C] Initial support for Carbon Events. 		10/16/00	GetClipRegion override is needed only for Carbon. 		10/16/00	Added Erase.		09/20/00	Include <windows.h>.		09/11/00	GetClipRegion method should only be used on the view's port. 					Same for GetVisRegion. 		09/08/00	Added SetBackgroundTheme.		08/01/00	[W] Added HandleWindowsEvent, DefaultWindowProcedure,					GetWindowsClassName, SetWindowsWindow, CreateWindowsWindow,					DeleteWindowsWindow and CreateWindowsWindowFromWDEF.  Removed					fWindowsWindow.		03/16/00	Use EXPORT_CLASS_MA.		02/22/00	[W] Added HandleWindowsEvent, DefaultWindowProcedure, fWindowsWindow 					and ReadFrom.  Include CStream_AC.h.  Exclude ProxyIcon-related functions.		07/27/99	Removed qAllegro test around SetProxyIconByFile, SetProxyIcon, GetProxyIcon,					SetModified, IsModified, TrackProxyDrag and HandlePathSelect.		07/08/99	The window no longer saves its update and visible regions when					it begins updating. GetUpdateRegion and GetVisRegion now go 					directly to the window's current update and visible regions. 					This makes MacApp's code more like the examples in Inside Mac. 					It fixes a bug where the non-debug version of GetUpdateRegion 					was returning LMGetSaveVisRgn, causing all the visible views to					redraw instead of just the ones that needed updating. 					This change could affect code that calls GetUpdateRegion or					GetVisRegion at draw time and expects the old MacApp behavior					instead of the toolbox compatible behavior. 		03/24/99	Update copyright notice.		03/22/99	[W] No DrawResizeIcon for Windows.		01/15/99	CAEDesc_AC is now in ACS. 		11/13/98	[2279281] Use qAllegro in place of qPowerPC && (UNIVERSAL_INTERFACES_VERSION >= 0x0320).		10/29/98	GetCommandContext can't be const since it might return 'this'.		10/26/98	Carbonize: change GetVisRegion and GetUpdateRegion from static to method;					add override of GetClipRegion; add data members for special Carbon regions		10/08/98	Undo context. 					Merge TCommandHandler into TEventHandler. */#ifndef __UWINDOW__#define __UWINDOW__// MacApp#ifndef __UCOMMAND__#include "UCommand.h"#endif#if qAppleEventAware	#ifndef __USCRIPTABLEOBJECT__	#include "UScriptableObject.h"	#endif#endif#ifndef __UVIEW__#include "UView.h"#endif// ACS#if qCarbonEvents	#ifndef __CCarbonEvent_AC__	#include "CCarbonEvent_AC.h"	#endif#endif#ifndef __CList_AC__#include "CList_AC.h"#endif#if qMSWindows	#ifndef __CStream_AC__	#include "CStream_AC.h"	#endif#endif#ifndef __CString_AC__#include "CString_AC.h"#endif#ifndef __CWindow_AC__#include "CWindow_AC.h"#endif#ifndef __TemplateArray_AC__#include "TemplateArray_AC.h"#endif// Toolbox#ifndef __QUICKDRAW__#include <Quickdraw.h>#endif#ifndef __APPEARANCE__#include <Appearance.h>#endif#if qMSWindows	#ifndef __WINDOWS__	#include <windows.h>	#endif#endif//----------------------------------------------------------------------------------// External and forward class declarations.//----------------------------------------------------------------------------------class CFile_AC;class TDialogBehavior;class TDocument;class TToolboxEvent;//----------------------------------------------------------------------------------// Constants//----------------------------------------------------------------------------------// ••• Moved to CWindow_AC//const short kFloatingWindowKind = 128;			// the windowKind of floating windowsconst DescType cPalette = 'cPal';#if qDragenum EDragCallbackStatus { eWindowNotInited, eNotInstalled, eInstalled };#endif // qDrag//----------------------------------------------------------------------------------// struct WindowFlags//----------------------------------------------------------------------------------struct WindowFlags{	private:		unsigned short fWindowFlagBits;		enum		{			kHasGoAwayMask = 0x8000,			kResizableMask = 0x4000,			kDoFirstClickMask = 0x2000,			kFreeOnClosingMask = 0x1000,			kDisposeOnFreeMask = 0x0800,			kClosesDocumentMask = 0x0400,			kOpenInitiallyMask = 0x0200,			kMustAdaptToScreenMask = 0x0100,			kStaggerMask = 0x0080,			kMustForceOnScreenMask = 0x0040,			kVertCenterMask = 0x0020,			kHorzCenterMask = 0x0010,			kFloatsMask = 0x0008,			kHideOnSuspendMask = 0x0004,			kGenerateActivatesMask = 0x0002			// note that the low bit is used as filler…		};		enum		{			kGenerateActivatesShift = 1,			kHideOnSuspendShift,			kFloatsShift,			kHorzCenterShift,			kVertCenterShift,			kMustForceOnScreenShift,			kStaggerShift,			kMustAdaptToScreenShift,			kOpenInitiallyShift,			kClosesDocumentShift,			kDisposeOnFreeShift,			kFreeOnClosingShift,			kDoFirstClickShift,			kResizableShift,			kHasGoAwayShift		};	public:		void Initialize() { fWindowFlagBits = 0x0000; }		bool GetHasGoAway() { return (fWindowFlagBits & kHasGoAwayMask) != 0; }		bool GetResizable() { return (fWindowFlagBits & kResizableMask) != 0; }		bool GetDoFirstClick() { return (fWindowFlagBits & kDoFirstClickMask) != 0; }		bool GetFreeOnClosing() { return (fWindowFlagBits & kFreeOnClosingMask) != 0; }		bool GetDisposeOnFree() { return (fWindowFlagBits & kDisposeOnFreeMask) != 0; }		bool GetClosesDocument() { return (fWindowFlagBits & kClosesDocumentMask) != 0; }		bool GetOpenInitially() { return (fWindowFlagBits & kOpenInitiallyMask) != 0; }		bool GetMustAdaptToScreen() { return (fWindowFlagBits & kMustAdaptToScreenMask) != 0; }		bool GetStagger() { return (fWindowFlagBits & kStaggerMask) != 0; }		bool GetMustForceOnScreen() { return (fWindowFlagBits & kMustForceOnScreenMask) != 0; }		bool GetVertCenter() { return (fWindowFlagBits & kVertCenterMask) != 0; }		bool GetHorzCenter() { return (fWindowFlagBits & kHorzCenterMask) != 0; }		bool GetFloats() { return (fWindowFlagBits & kFloatsMask) != 0; }		bool GetHideOnSuspend() { return (fWindowFlagBits & kHideOnSuspendMask) != 0; }		bool GetGenerateActivates() { return (fWindowFlagBits & kGenerateActivatesMask) != 0; }		void SetHasGoAway(unsigned short hasGoAway) { fWindowFlagBits |= hasGoAway << kHasGoAwayShift; }		void SetResizable(unsigned short resizable) { fWindowFlagBits |= resizable << kResizableShift; }		void SetDoFirstClick(unsigned short doFirstClick) { fWindowFlagBits |= doFirstClick << kDoFirstClickShift; }		void SetFreeOnClosing(unsigned short freeOnClosing) { fWindowFlagBits |= freeOnClosing << kFreeOnClosingShift; }		void SetDisposeOnFree(unsigned short disposeOnFree) { fWindowFlagBits |= disposeOnFree << kDisposeOnFreeShift; }		void SetClosesDocument(unsigned short closesDocument) { fWindowFlagBits |= closesDocument << kClosesDocumentShift; }		void SetOpenInitially(unsigned short openInitially) { fWindowFlagBits |= openInitially << kOpenInitiallyShift; }		void SetMustAdaptToScreen(unsigned short mustAdaptToScreen) { fWindowFlagBits |= mustAdaptToScreen << kMustAdaptToScreenShift; }		void SetStagger(unsigned short stagger) { fWindowFlagBits |= stagger << kStaggerShift; }		void SetMustForceOnScreen(unsigned short mustForceOnScreen) { fWindowFlagBits |= mustForceOnScreen << kMustForceOnScreenShift; }		void SetVertCenter(unsigned short vertCenter) { fWindowFlagBits |= vertCenter << kVertCenterShift; }		void SetHorzCenter(unsigned short horzCenter) { fWindowFlagBits |= horzCenter << kHorzCenterShift; }		void SetFloats(unsigned short floats) { fWindowFlagBits |= floats << kFloatsShift; }		void SetHideOnSuspend(unsigned short hideOnSuspend) { fWindowFlagBits |= hideOnSuspend << kHideOnSuspendShift; }		void SetGenerateActivates(unsigned short generateActivates) { fWindowFlagBits |= generateActivates << kGenerateActivatesShift; }#if qMSWindows		void ReadFrom(CStream_AC* aStream) { fWindowFlagBits = aStream->ReadUnsignedShort(); }#endif};//----------------------------------------------------------------------------------------// CWindowAndWindowRef: Used by the window mapper//----------------------------------------------------------------------------------------struct CWindowAndWindowRef{	CWindowAndWindowRef() { }	CWindowAndWindowRef(TWindow* inTWindow, WindowRef inWindowRef) :	fTWindow(inTWindow),	fWindowRef(inWindowRef)	{ }	TWindow* fTWindow;	WindowRef fWindowRef;	CompareResult_AC Compare(const CWindowAndWindowRef& criteria) const;};//----------------------------------------------------------------------------------------// procedure typedefs for parameters//----------------------------------------------------------------------------------------typedef CompareResult_AC (*CompareWindowRefType)(WindowRef anItem, void* yourDataPtr);//----------------------------------------------------------------------------------// CWindowRefTable: A table of window references.//----------------------------------------------------------------------------------EXPORT_CLASS_MA(TemplateSortedArray_AC<CWindowAndWindowRef>)EXPORT_CLASS_MA(TemplateArrayIterator_AC<CWindowAndWindowRef>)class EXPORT_MA CWindowRefTable : public TemplateSortedArray_AC<CWindowAndWindowRef>{public:	CWindowRefTable() { }	virtual ~CWindowRefTable() { }		// Destructor	void Delete(const WindowRef item);	virtual CompareResult_AC Compare(const CWindowAndWindowRef& record1,										 const CWindowAndWindowRef& record2) const;		// Compare TWindowAndWindowRef's.};//----------------------------------------------------------------------------------// TWindow: Corresponds to a desktop Window. The outermost of a nested set of views.//----------------------------------------------------------------------------------class EXPORT_MA TWindow : public TView#if qAppleEventAware						, public MScriptableObject#endif// The TWindow class is a subclass of TView whose objects represent// Window Manager windows. TWindow objects never have superviews,// and they must have at least one subview in order to draw in the// window's content region.{	//------------------------------------------------------------------------------------	// Creation/ Destruction Methods	//------------------------------------------------------------------------------------public:	TWindow(WindowRef itsWMgrWindow = NULL,					  bool canResize = true,					  bool canClose = true,					  bool inDispose = false);		// Constructor	TWindow(const TWindow& inWindow);		// Copy Constructor	virtual ~TWindow();		// Frees the window if fDisposeOnFree is true, also deletes the window from the        // document if there is one, otherwise deletes it from the applications list of        // free windows.	virtual void* Clone() const;	virtual WindowRef GetBehindWindowPtr() const;		// return the windowPtr in the windowlist behind which this window gets created	virtual void DoPostCreate(TDocument* itsDocument);		// sets the resize limits	virtual void CreateToolboxWindow();		// Create the toolbox window. #if !qMSWindows#if !qCarbon	virtual void CreateClassicWindow();		// Create a window using the old style NewCWindow calls. #endif#if qPowerPC	virtual void CreateAppearanceWindow();		// Create a window using the new style CreateWindow calls. 	virtual void GetCreateParameters(short procID, WindowClass& windowClass, 									 WindowAttributes& attributes) const;		// Convert an old style procID to parameters for create window. May be overridden. #endif // qPowerPC#endif // !qMSWindows	//------------------------------------------------------------------------------------	// Standard signature support.	//------------------------------------------------------------------------------------	virtual IDType GetStandardSignature() const;		// Returns this class's standard signature.	//------------------------------------------------------------------------------------	// Stream I/O protocol support.	//------------------------------------------------------------------------------------	virtual void ReadFields(CStream_AC* aStream);	virtual void WriteFields(CStream_AC* aStream) const;	//------------------------------------------------------------------------------------	// Open/Close Methods	//------------------------------------------------------------------------------------	virtual void BeInDocument(TDocument* itsDocument);		// Assigns fDocument itsDocument by calling Inherited and then adds		// itself to the document's window list	virtual void Open();		// Makes the window visible by showing it before calling Inherited::Open.	virtual void DoClose(CommandNumber aCommand , bool useAppleEvent = true );		// Creates and posts a command which will close the window.  Pass a false		// if the command is not to create an AppleEvent.	virtual void Close();		// Calls Inherited::Close and the hides & deactivates the window.	void CloseAndFree();		// Calls Close and delete for the window if fFreeOnClosing.		//••• This method will be removed, please call Close and then if necessary call delete	virtual void CloseByUser(CommandNumber aCommandNumber);		// If the window is shown and it can be closed handles the closing.		// Returns false if the user cancels closing.	virtual void GoAwayByUser(const CViewPoint& theMouse);		// Responsible for calling CloseByUser.	//------------------------------------------------------------------------------------	// Activation Methods	//------------------------------------------------------------------------------------	virtual void SetActiveState(bool beActive, bool redraw); // Activate(bool entering);		// Activate the window.	//------------------------------------------------------------------------------------	// Size/ Location Methods	//------------------------------------------------------------------------------------	virtual void MoveByUser(const CViewPoint& theMouse);		// Handles the user moving the window by dragging the title bar, calls DragWindow        // to handle movement.	virtual void ResizeByUser(const CViewPoint& theMouse);		// Handles the user resizing the window by dragging the growbox, calls GrowWindow        // to handle movement and Resize to resize the window.	virtual void SetFrame(const CViewRect& newFrame, bool invalidate);		// Used to resize the window by setting its frame to the parameters        // passed in.	virtual void Zoom(short partCode);		// Responsible for actually handling the zooming of a window when the user clicks        // in the zoombox.	virtual void ZoomByUser(const CViewPoint& theMouse, short partCode);		// handles the user clicking in the zoombox to zoom the window, calls Zoom.	virtual CRect_AC GetDynamicMoveBounds() const;		// returns bounds over which the window may be moved. Honors fMoveBounds when non-zero	virtual CRect_AC GetDynamicResizeLimits() const;		// returns limits over which the window may be resized. Honors fResizeLimits when non-zero.	//------------------------------------------------------------------------------------	// Focusing Methods	//------------------------------------------------------------------------------------	virtual bool Focus();		// Attempts to set the Focus to the window, returns true if it succeeds, false if        // not.	virtual bool FocusOnSuperView();		// Attempts to set the Focus to our superview, returning true if it succeeds or        // false if not.	//------------------------------------------------------------------------------------	// Drawing Methods	//------------------------------------------------------------------------------------#if !qMSWindows	virtual void DrawResizeIcon();		// Draws the grow icon by calling the toolbox routine DrawGrowIcon.#endif	void SetBackgroundTheme(ThemeBrush theBrush, bool invalidate = true);		// Sets the window's Appearance background theme.	//------------------------------------------------------------------------------------	// Mouse Handling Methods	//------------------------------------------------------------------------------------	virtual bool HandleMouseDown(const CViewPoint& theMouse,										   TToolboxEvent* event,										   CPoint_AC hysteresis,										   EMouseDownType mouseDownType = kDragOrClick);		// Handles mouse downs in the window.	virtual short GetPartCode(const CViewPoint& theMouse) const;		// determines what part of the window theMouse is in	virtual bool HasPendingUpdate();	// was const		// Returns true if there is a pending update event for this window, false if not.	virtual void BeginUpdate();		// Encapsulates the Toolbox BeginUpdate.	virtual void EndUpdate();		// Encapsulates the Toolbox EndUpdate.	virtual void Update();		// Handle the update region and drawcontents on this.	virtual void Erase();		// Handle erasing of the window's extent.	virtual void DoInvalidateRegion(const RgnHandle badRgn);		// If a WMgrWindow is available calls InvalRgn	virtual void 